import React, { useState } from 'react';
import { saveToSheet } from '../services/api';

const BMICalculator: React.FC = () => {
  const [bmi, setBmi] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [inputs, setInputs] = useState({
    name: '',
    phone: '',
    gender: 'Male',
    weight: '',
    height: '' // in cm
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setInputs({ ...inputs, [e.target.name]: e.target.value });
  };

  const calculateBMI = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    const weight = parseFloat(inputs.weight);
    const heightM = parseFloat(inputs.height) / 100;

    if (weight > 0 && heightM > 0) {
      const bmiValue = parseFloat((weight / (heightM * heightM)).toFixed(1));
      setBmi(bmiValue);

      // Save to API
      await saveToSheet({
        date: new Date().toLocaleDateString(),
        name: inputs.name,
        phone: inputs.phone,
        weight: inputs.weight,
        height: inputs.height,
        goal: `BMI Score: ${bmiValue}`, // Saving BMI in goal column
        type: inputs.gender
      });
    }
    setLoading(false);
  };

  // Helper for gauge rotation: Map BMI 15-40 to -90deg to 90deg
  const getRotation = (value: number) => {
    const minBMI = 15;
    const maxBMI = 40;
    const clamped = Math.max(minBMI, Math.min(value, maxBMI));
    const percentage = (clamped - minBMI) / (maxBMI - minBMI);
    return -90 + (percentage * 180);
  };

  const getStatus = (val: number) => {
    if (val < 18.5) return { text: "Underweight", color: "text-yellow-400" };
    if (val < 25) return { text: "Normal", color: "text-emerald-400" };
    return { text: "Health at Risk", color: "text-red-500" };
  };

  return (
    <section className="py-20 bg-slate-900 border-t border-slate-800">
      <div className="container mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-extrabold text-white">BMI Calculator</h2>
          <p className="text-gray-400">Check your health metrics instantly.</p>
        </div>

        <div className="max-w-4xl mx-auto grid md:grid-cols-2 gap-10">
            {/* Form */}
            <form onSubmit={calculateBMI} className="space-y-5">
                 <input type="text" name="name" required placeholder="Name" className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-white focus:ring-emerald-500" onChange={handleChange} />
                 <input type="tel" name="phone" required placeholder="Phone" className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-white focus:ring-emerald-500" onChange={handleChange} />
                 <select name="gender" className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-white" onChange={handleChange}>
                     <option>Male</option>
                     <option>Female</option>
                 </select>
                 <div className="flex gap-4">
                     <input type="number" name="weight" required placeholder="Weight (kg)" className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-white" onChange={handleChange} />
                     <input type="number" name="height" required placeholder="Height (cm)" className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-white" onChange={handleChange} />
                 </div>
                 <button type="submit" disabled={loading} className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-3 rounded-xl transition-colors">
                     {loading ? 'Calculating...' : 'Calculate BMI'}
                 </button>
            </form>

            {/* Visual Gauge */}
            <div className="flex flex-col items-center justify-center glass-dark rounded-3xl p-6">
                <div className="relative w-64 h-32 overflow-hidden mb-4">
                    {/* Gauge Background */}
                    <div className="w-full h-full bg-slate-700 rounded-t-full relative">
                        <div className="absolute bottom-0 w-full h-full" 
                             style={{ background: 'conic-gradient(from 180deg at 50% 100%, #ef4444 0deg, #eab308 50deg, #10b981 90deg, #eab308 130deg, #ef4444 180deg)' }}>
                        </div>
                    </div>
                    {/* Needle */}
                    <div 
                        className="absolute bottom-0 left-1/2 w-1 h-28 bg-white origin-bottom rounded-full transition-transform duration-1000 ease-out z-10"
                        style={{ transform: `translateX(-50%) rotate(${bmi ? getRotation(bmi) : -90}deg)` }}
                    ></div>
                    {/* Pivot */}
                    <div className="absolute bottom-0 left-1/2 w-4 h-4 bg-white rounded-full -translate-x-1/2 translate-y-1/2 z-20"></div>
                </div>

                {bmi ? (
                    <div className="text-center animate-fade-in-up">
                        <span className="text-5xl font-black text-white">{bmi}</span>
                        <p className={`text-xl font-bold mt-2 ${getStatus(bmi).color}`}>
                            {getStatus(bmi).text}
                        </p>
                    </div>
                ) : (
                    <p className="text-gray-400">Enter details to see your score</p>
                )}
            </div>
        </div>
      </div>
    </section>
  );
};

export default BMICalculator;

